from typing import Any, Dict, List

import boto3

def create_textract_client() -> boto3.client:
    return boto3.client('textract')

def create_ocr_request(document_bytes: bytes) -> Dict[str, Any]:
    return {
        'Document': {
            'Bytes': document_bytes
        }
    }

def create_layout_request(document_bytes: bytes) -> Dict[str, Any]:
    return {
        'Document': {
            'Bytes': document_bytes
        }
    }

def normalize_ocr_response(response: Dict[str, Any]) -> List[Dict[str, Any]]:
    normalized_response = []
    for item in response.get('Blocks', []):
        if item['BlockType'] == 'LINE':
            normalized_response.append({
                'text': item.get('Text', ''),
                'confidence': item.get('Confidence', 0.0)
            })
    return normalized_response

def normalize_layout_response(response: Dict[str, Any]) -> List[Dict[str, Any]]:
    normalized_response = []
    for item in response.get('Blocks', []):
        if item['BlockType'] == 'LAYOUT_CELL':
            normalized_response.append({
                'text': item.get('Text', ''),
                'confidence': item.get('Confidence', 0.0)
            })
    return normalized_response

import boto3

def configure_textract_client(region_name='us-west-2'):
    return boto3.client('textract', region_name=region_name)

def extract_text(document_bytes):
    client = configure_textract_client()
    response = client.detect_document_text(Document={'Bytes': document_bytes})
    return response

def extract_layout(document_bytes):
    client = configure_textract_client()
    response = client.analyze_document(Document={'Bytes': document_bytes}, FeatureTypes=['TABLES', 'FORMS'])
    return response

import boto3

def extract_key_values(document_path):
    textract = boto3.client('textract')
    with open(document_path, 'rb') as document:
        response = textract.analyze_document(
            Document={'Bytes': document.read()},
            FeatureTypes=['FORMS'])
    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = next((child for child in block['Relationships'] if child['Type'] == 'CHILD'), None)
            value = next((child for child in block['Relationships'] if child['Type'] == 'VALUE'), None)
            if key and value:
                key_text = next((text['Text'] for text in response['Blocks'] if text['Id'] == key['Ids'][0] and text['BlockType'] == 'WORD'), None)
                value_text = next((text['Text'] for text in response['Blocks'] if text['Id'] == value['Ids'][0] and text['BlockType'] == 'WORD'), None)
                if key_text and value_text:
                    key_values[key_text] = value_text
    return key_values

import boto3

def extract_tables(document_path):
    textract = boto3.client('textract')
    with open(document_path, 'rb') as document:
        response = textract.analyze_document(
            Document={'Bytes': document.read()},
            FeatureTypes=['TABLES'])
    tables = []
    for table in response['Blocks']:
        if table['BlockType'] == 'TABLE':
            table_data = {
                'Rows': [],
                'Columns': []
            }
            for relationship in table['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child_block = next(block for block in response['Blocks'] if block['Id'] == child_id)
                        if child_block['BlockType'] == 'CELL':
                            row_index = child_block['RowIndex']
                            column_index = child_block['ColumnIndex']
                            cell_text = child_block['Text']
                            if len(table_data['Rows']) <= row_index:
                                table_data['Rows'].append([])
                            if len(table_data['Columns']) <= column_index:
                                table_data['Columns'].append([])
                            table_data['Rows'][row_index-1].append(cell_text)
                            table_data['Columns'][column_index-1].append(cell_text)
            tables.append(table_data)
    return tables

if __name__ == '__main__':
    document_path = 'sample_document.pdf'
    tables = extract_tables(document_path)
    for table in tables:
        print(table)
